def transform(grid):
    border = grid[0][0]
    h, w = len(grid), len(grid[0])
    rows3 = [r for r in range(h) if any(v == 3 for v in grid[r])]
    cols3 = [c for c in range(w) if any(grid[r][c] == 3 for r in range(h))]
    vertical = max(sum(grid[r][c] == 3 for r in range(h)) for c in range(w)) > max(sum(v == 3 for v in row) for row in grid)
    out = [[0] * w for _ in range(h)]
    if vertical:
        two_rows = [r for r in range(h) if 2 in grid[r]]
        starts = [r for r in two_rows if r - 1 not in two_rows]
        period = starts[1] - starts[0]
        for r in range(h):
            source = starts[0] + (r - starts[0]) % period
            for c in range(w):
                if grid[source][c] == 2:
                    out[r][c] = 2
                elif c in cols3:
                    out[r][c] = 3
                elif 2 in grid[source]:
                    out[r][c] = border
    else:
        two_cols = [c for c in range(w) if any(grid[r][c] == 2 for r in range(h))]
        starts = [c for c in two_cols if c - 1 not in two_cols]
        period = starts[1] - starts[0]
        for r in range(h):
            for c in range(w):
                source = starts[0] + (c - starts[0]) % period
                if grid[r][source] == 2:
                    out[r][c] = 2
                elif r in rows3:
                    out[r][c] = 3
                elif 2 in [grid[rr][source] for rr in range(h)]:
                    out[r][c] = border
    return out

